REPLACE MACRO SALES.mLoadDay (d DATE) AS (
  DEL FROM SALES.EventLog WHERE CAST(EventTs AS DATE) = :d;
  INS INTO SALES.EventLog SEL * FROM STG.Events WHERE CAST(EventTs AS DATE FORMAT 'YYYY-MM-DD') = :d;
);

REPLACE PROCEDURE SALES.spRecalc()
BEGIN
  MERGE INTO SALES.Customers c USING (SEL CustomerId, ZEROIFNULL(SUM(Amount)) s FROM SALES.Orders GROUP BY 1) o
  ON c.CustomerId = o.CustomerId
  WHEN MATCHED THEN UPDATE SET Segment = CASE WHEN o.s > 1000 THEN 1 ELSE 0 END;
END;
